// =============================================================================
// Frappe Web Form Client Script
// DocType: Supplier Registration
// =============================================================================
//
// PURPOSE
// -------
// Client-side validation, normalization and duplicate checking for supplier
// registration.
//
// FEATURES
// --------
// - GSTIN format, state-code and checksum validation.
// - Automatic PAN extraction from a valid GSTIN.
// - GSTIN/PAN synchronization.
// - PAN format validation.
// - Email format validation and normalization.
// - Mobile number normalization to E.164.
// - GSTIN vs selected State validation.
// - PIN Code vs selected State advisory validation.
// - Supplier Name validation.
// - Duplicate GSTIN / PAN / Email / Mobile / Supplier Name checks.
// - India-only validation gating.
// - Non-blocking validation on field blur.
// - Blocking validation during submission.
//
// DUPLICATE CHECK DESIGN
// ----------------------
// Duplicate checks are cached by:
//
//     field + normalized value
//
// Therefore:
//
//     Same value + already checked  -> cached result is reused.
//     Same value + request pending  -> existing request is reused.
//     New value                    -> new request is started.
//     Failed request               -> next validation retries it.
//
// Each request also receives a request ID. This prevents an older asynchronous
// response from overwriting the result belonging to a newer request.
//
// IMPORTANT
// ---------
// Client-side validation is for user experience. Server-side validation must
// remain authoritative for uniqueness and data integrity.
// =============================================================================

(() => {
	"use strict";

	// =========================================================================
	// 1. CONFIGURATION
	// =========================================================================

	const CONFIG = {
		// ---------------------------------------------------------------------
		// Web Form field names
		// ---------------------------------------------------------------------
		fields: {
			gstin: "gstin",
			pan: "pan",
			email: "email",
			mobile: "mobile",
			state: "state",
			pincode: "pincode",
			supplierName: "supplier_name",
			country: "country"
		},

		// ---------------------------------------------------------------------
		// Default country calling code for Indian mobile numbers
		// ---------------------------------------------------------------------
		defaultCountryCode: "91",

		// ---------------------------------------------------------------------
		// Server-side duplicate check method
		// ---------------------------------------------------------------------
		duplicateCheckMethod: "sas_fortuna.api.supplier_registration.check_duplicate_supplier",

		// ---------------------------------------------------------------------
		// Validation patterns
		// ---------------------------------------------------------------------
		patterns: {
			// Indian GSTIN:
			// State Code + PAN + Entity Number + Z + Checksum
			gstin: /^(0[1-9]|[1-2]\d|3[0-8]|97|99)[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/,

			// Indian PAN
			pan: /^[A-Z]{5}\d{4}[A-Z]$/,

			// Basic email format
			email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,

			// E.164 international phone format
			mobile: /^\+[1-9]\d{7,14}$/,

			// Indian PIN code
			pincode: /^[1-9]\d{5}$/
		},

		// ---------------------------------------------------------------------
		// Base-36 character set used by GSTIN checksum
		// ---------------------------------------------------------------------
		gstinCharset: "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ",

		// ---------------------------------------------------------------------
		// GST state codes
		// ---------------------------------------------------------------------
		gstStateCodes: {
			"01": ["Jammu and Kashmir"],
			"02": ["Himachal Pradesh"],
			"03": ["Punjab"],
			"04": ["Chandigarh"],
			"05": ["Uttarakhand"],
			"06": ["Haryana"],
			"07": ["Delhi"],
			"08": ["Rajasthan"],
			"09": ["Uttar Pradesh"],
			"10": ["Bihar"],
			"11": ["Sikkim"],
			"12": ["Arunachal Pradesh"],
			"13": ["Nagaland"],
			"14": ["Manipur"],
			"15": ["Mizoram"],
			"16": ["Tripura"],
			"17": ["Meghalaya"],
			"18": ["Assam"],
			"19": ["West Bengal"],
			"20": ["Jharkhand"],
			"21": ["Odisha"],
			"22": ["Chhattisgarh"],
			"23": ["Madhya Pradesh"],
			"24": ["Gujarat"],
			"25": [
				"Daman and Diu",
				"Dadra and Nagar Haveli and Daman and Diu"
			],
			"26": [
				"Dadra and Nagar Haveli",
				"Dadra and Nagar Haveli and Daman and Diu"
			],
			"27": ["Maharashtra"],
			"28": ["Andhra Pradesh"],
			"29": ["Karnataka"],
			"30": ["Goa"],
			"31": ["Lakshadweep"],
			"32": ["Kerala"],
			"33": ["Tamil Nadu"],
			"34": ["Puducherry"],
			"35": ["Andaman and Nicobar Islands"],
			"36": ["Telangana"],
			"37": ["Andhra Pradesh"],
			"38": ["Ladakh"],
			"97": ["Other Territory"],
			"99": ["Centre Jurisdiction"]
		},

		// ---------------------------------------------------------------------
		// Coarse PIN first-digit -> State mapping.
		//
		// This is advisory only because a PIN prefix can cover multiple states.
		// ---------------------------------------------------------------------
		pincodeFirstDigitStates: {
			"1": [
				"Delhi",
				"Haryana",
				"Punjab",
				"Himachal Pradesh",
				"Jammu and Kashmir",
				"Chandigarh",
				"Ladakh"
			],

			"2": [
				"Uttar Pradesh",
				"Uttarakhand"
			],

			"3": [
				"Rajasthan",
				"Gujarat",
				"Daman and Diu",
				"Dadra and Nagar Haveli",
				"Dadra and Nagar Haveli and Daman and Diu"
			],

			"4": [
				"Maharashtra",
				"Madhya Pradesh",
				"Chhattisgarh",
				"Goa"
			],

			"5": [
				"Andhra Pradesh",
				"Telangana",
				"Karnataka"
			],

			"6": [
				"Tamil Nadu",
				"Kerala",
				"Puducherry",
				"Lakshadweep"
			],

			"7": [
				"West Bengal",
				"Odisha",
				"Andaman and Nicobar Islands",
				"Sikkim",
				"Assam",
				"Arunachal Pradesh",
				"Nagaland",
				"Manipur",
				"Mizoram",
				"Tripura",
				"Meghalaya"
			],

			"8": [
				"Bihar",
				"Jharkhand"
			],

			"9": []
		},

		// ---------------------------------------------------------------------
		// User-facing messages
		// ---------------------------------------------------------------------
		messages: {
			gstinInvalidShape: "Please enter a valid 15-character GSTIN (e.g., 27AAAAA0000A1Z5).",

			gstinInvalidChecksum: "GSTIN check digit verification failed. Please check for typos.",

			panSyncedFromGstin: (
					previousValue,
					extractedPan
				) =>
				`PAN has been set to ${extractedPan} from the GSTIN, replacing ${previousValue}.`,

			panInvalid: "Please enter a valid 10-character PAN (e.g., AAAAA0000A).",

			emailInvalid: "Please enter a valid email address (e.g., name@example.com).",

			mobileInvalid: "Please enter a valid mobile number with country code (e.g., +919876543210).",

			pincodeInvalid: "Please enter a valid 6-digit PIN code.",

			gstinStateMismatch: (
					gstinStates,
					selectedState
				) =>
				`Note: The GSTIN's state (${gstinStates.join(" / ")}) does not match the selected State (${selectedState}).`,

			pincodeStateMismatch: (
					pincode,
					selectedState
				) =>
				`Note: PIN code ${pincode} doesn't look like it's in ${selectedState} - please double check.`,

			supplierNameTooGeneric: 'Supplier Name cannot be just "Supplier" - please enter the actual company or person name.',

			duplicateGstin: "This GSTIN is already registered with another supplier.",

			duplicatePan: "This PAN is already registered with another supplier.",

			duplicateEmail: "This email address is already registered with another supplier.",

			duplicateMobile: "This mobile number is already registered with another supplier.",

			duplicateSupplierName: "A supplier with this name is already registered.",

			duplicateCheckPending: "Still confirming your details aren't already registered - please click Submit again in a moment."
		}
	};

	// =========================================================================
	// 2. NOTIFICATION HELPERS
	// =========================================================================

	const NOTIFICATION_SUPPRESSION_MS = 1000;

	let lastNotification = {
		message: null,
		timestamp: 0
	};

	/**
	 * Display a validation/advisory message.
	 *
	 * Identical messages shown repeatedly within a short interval are ignored
	 * to prevent notification spam.
	 */
	function notify(
		message, {
			isBlocking = false,
			indicator = "orange"
		} = {}
	) {
		const now = Date.now();

		if (
			lastNotification.message === message &&
			now - lastNotification.timestamp <
			NOTIFICATION_SUPPRESSION_MS
		) {
			return;
		}

		lastNotification = {
			message,
			timestamp: now
		};

		if (isBlocking) {
			frappe.msgprint({
				title: __("Validation Error"),
				indicator: "red",
				message: __(message)
			});

			return;
		}

		if (
			typeof frappe.show_alert ===
			"function"
		) {
			frappe.show_alert({
					message,
					indicator
				},
				6
			);
		} else {
			frappe.msgprint(message);
		}
	}

	// =========================================================================
	// 3. GENERIC FIELD HELPERS
	// =========================================================================

	/**
	 * Read a Web Form field safely.
	 */
	function getValue(fieldname) {
		return (
			frappe.web_form.get_value(
				fieldname
			) || ""
		);
	}

	/**
	 * Set a Web Form field only when the value actually changes.
	 *
	 * This avoids unnecessary change events.
	 */
	function setValue(fieldname, value) {
		if (
			getValue(fieldname) !== value
		) {
			frappe.web_form.set_value(
				fieldname,
				value
			);
		}
	}

	/**
	 * Read and trim a field value.
	 */
	function trimValue(fieldname) {
		const rawValue =
			getValue(fieldname);

		const trimmed =
			String(rawValue).trim();

		if (
			rawValue &&
			rawValue !== trimmed
		) {
			setValue(
				fieldname,
				trimmed
			);
		}

		return trimmed;
	}

	/**
	 * Normalize state names before comparison.
	 */
	function normalizeStateName(value) {
		return String(value || "")
			.trim()
			.toLowerCase()
			.replace(/&/g, "and")
			.replace(/\s+/g, " ");
	}

	// =========================================================================
	// 4. COUNTRY / INDIA HELPERS
	// =========================================================================

	/**
	 * Determine whether India-specific validation should run.
	 *
	 * Blank Country is intentionally treated as India.
	 */
	function isIndiaSelected() {
		const country =
			trimValue(
				CONFIG.fields.country
			);

		return (
			!country ||
			country.toLowerCase() ===
			"india"
		);
	}

	// =========================================================================
	// 5. GSTIN CHECKSUM / EXTRACTION
	// =========================================================================

	/**
	 * Validate GSTIN using the Modulo-36 Luhn-variant checksum.
	 */
	function isValidGstinChecksum(
		gstin
	) {
		let factor = 2;
		let sum = 0;

		// Process every character except the final check digit.
		for (
			let index =
				gstin.length - 2; index >= 0; index--
		) {
			const codePoint =
				CONFIG.gstinCharset.indexOf(
					gstin[index]
				);

			if (codePoint === -1) {
				return false;
			}

			const product =
				factor * codePoint;

			sum +=
				Math.floor(
					product / 36
				) +
				(product % 36);

			factor =
				factor === 2 ? 1 : 2;
		}

		const expectedCodePoint =
			(36 - (sum % 36)) % 36;

		const expectedCheckCharacter =
			CONFIG.gstinCharset[
				expectedCodePoint
			];

		return (
			expectedCheckCharacter ===
			gstin[gstin.length - 1]
		);
	}

	/**
	 * Extract PAN from a GSTIN.
	 */
	function getPanFromGstin(gstin) {
		return gstin.substring(2, 12);
	}

	/**
	 * Extract State Code from a GSTIN.
	 */
	function getStateCodeFromGstin(
		gstin
	) {
		return gstin.substring(0, 2);
	}

	/**
	 * Return a GSTIN only when both shape and checksum are valid.
	 */
	function getValidatedGstin() {
		const gstin =
			trimValue(
				CONFIG.fields.gstin
			).toUpperCase();

		if (!gstin) {
			return null;
		}

		if (
			!CONFIG.patterns.gstin.test(
				gstin
			)
		) {
			return null;
		}

		if (
			!isValidGstinChecksum(
				gstin
			)
		) {
			return null;
		}

		return gstin;
	}

	// =========================================================================
	// 6. GSTIN -> PAN SYNCHRONIZATION
	// =========================================================================

	/**
	 * Synchronize PAN from a valid GSTIN.
	 *
	 * GSTIN is treated as the authoritative source for PAN because PAN is
	 * embedded within the GSTIN.
	 */
	function syncPanFromGstin(
		gstin,
		showNotification = true
	) {
		const extractedPan =
			getPanFromGstin(gstin);

		const currentPan =
			trimValue(
				CONFIG.fields.pan
			).toUpperCase();

		if (
			showNotification &&
			currentPan &&
			currentPan !== extractedPan
		) {
			notify(
				CONFIG.messages
				.panSyncedFromGstin(
					currentPan,
					extractedPan
				)
			);
		}

		setValue(
			CONFIG.fields.pan,
			extractedPan
		);

		/*
		 * Synchronize the actual input element as well.
		 *
		 * This is useful with Web Form implementations where the displayed
		 * input value may be maintained separately from the model value.
		 */
		const panField =
			frappe.web_form.fields_dict &&
			frappe.web_form.fields_dict[
				CONFIG.fields.pan
			];

		if (
			panField &&
			panField.$input &&
			typeof panField.$input.val ===
			"function"
		) {
			panField.$input.val(
				extractedPan
			);
		}

		return extractedPan;
	}

	// =========================================================================
	// 7. GSTIN / STATE VALIDATION
	// =========================================================================

	/**
	 * Verify GSTIN state code against the selected State.
	 */
	function validateGstinState(
		gstin,
		isSubmitting = false
	) {
		const selectedState =
			trimValue(
				CONFIG.fields.state
			);

		if (!selectedState) {
			return true;
		}

		const stateCode =
			getStateCodeFromGstin(
				gstin
			);

		const acceptedStates =
			CONFIG.gstStateCodes[
				stateCode
			];

		// Unknown mapping is not treated as a validation failure.
		if (!acceptedStates) {
			return true;
		}

		const normalizedSelectedState =
			normalizeStateName(
				selectedState
			);

		const matches =
			acceptedStates.some(
				(stateName) =>
				normalizeStateName(
					stateName
				) ===
				normalizedSelectedState
			);

		if (matches) {
			return true;
		}

		notify(
			CONFIG.messages
			.gstinStateMismatch(
				acceptedStates,
				selectedState
			), {
				isBlocking: isSubmitting
			}
		);

		return false;
	}

	// =========================================================================
	// 8. GSTIN VALIDATION
	// =========================================================================

	/**
	 * Validate GSTIN, synchronize PAN and start duplicate checking.
	 */
	function validateGstin(
		value,
		isSubmitting = false
	) {
		if (!isIndiaSelected()) {
			return true;
		}

		const gstin =
			String(value || "")
			.trim()
			.toUpperCase();

		if (!gstin) {
			return true;
		}

		setValue(
			CONFIG.fields.gstin,
			gstin
		);

		// Validate basic GSTIN structure first.
		if (
			!CONFIG.patterns.gstin.test(
				gstin
			)
		) {
			notify(
				CONFIG.messages
				.gstinInvalidShape, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// Validate the final checksum character.
		if (
			!isValidGstinChecksum(
				gstin
			)
		) {
			notify(
				CONFIG.messages
				.gstinInvalidChecksum, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// Valid GSTIN is authoritative for PAN.
		syncPanFromGstin(gstin);

		// GSTIN and State must agree.
		if (
			!validateGstinState(
				gstin,
				isSubmitting
			)
		) {
			return false;
		}

		// Start/reuse duplicate check.
		ensureDuplicateCheck(
			"gstin",
			gstin
		);

		return true;
	}

	// =========================================================================
	// 9. PAN VALIDATION
	// =========================================================================

	/**
	 * Validate PAN.
	 *
	 * When a valid GSTIN exists, the GSTIN-derived PAN takes precedence.
	 */
	function validatePan(
		value,
		isSubmitting = false
	) {
		if (!isIndiaSelected()) {
			return true;
		}

		let pan =
			String(value || "")
			.trim()
			.toUpperCase();

		if (!pan) {
			return true;
		}

		// If GSTIN is valid, synchronize PAN from GSTIN.
		const validatedGstin =
			getValidatedGstin();

		if (validatedGstin) {
			const expectedPan =
				getPanFromGstin(
					validatedGstin
				);

			if (
				pan !== expectedPan
			) {
				syncPanFromGstin(
					validatedGstin,
					true
				);

				// Continue using the authoritative GSTIN-derived PAN.
				pan = expectedPan;
			}
		}

		setValue(
			CONFIG.fields.pan,
			pan
		);

		if (
			!CONFIG.patterns.pan.test(
				pan
			)
		) {
			notify(
				CONFIG.messages.panInvalid, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// Start/reuse duplicate check.
		ensureDuplicateCheck(
			"pan",
			pan
		);

		return true;
	}

	// =========================================================================
	// 10. EMAIL VALIDATION
	// =========================================================================

	/**
	 * Normalize and validate email address.
	 */
	function validateEmail(
		value,
		isSubmitting = false
	) {
		const email =
			String(value || "")
			.trim()
			.toLowerCase();

		if (!email) {
			return true;
		}

		setValue(
			CONFIG.fields.email,
			email
		);

		if (
			!CONFIG.patterns.email.test(
				email
			)
		) {
			notify(
				CONFIG.messages
				.emailInvalid, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// Start/reuse duplicate check.
		ensureDuplicateCheck(
			"email",
			email
		);

		return true;
	}

	// =========================================================================
	// 11. MOBILE NORMALIZATION / VALIDATION
	// =========================================================================

	/**
	 * Normalize common Indian mobile formats to E.164.
	 *
	 * Examples:
	 *
	 *     9876543210
	 *     -> +919876543210
	 *
	 *     09876543210
	 *     -> +919876543210
	 *
	 *     919876543210
	 *     -> +919876543210
	 */
	function normalizeMobileNumber(
		value,
		useIndiaDefault = true
	) {
		if (!value) {
			return "";
		}

		const cleaned =
			String(value).replace(
				/[\s\-().]/g,
				""
			);

		if (!useIndiaDefault) {
			return cleaned;
		}

		const countryCode =
			CONFIG.defaultCountryCode;

		// 09876543210 -> +919876543210
		if (
			/^0\d{10}$/.test(cleaned)
		) {
			return (
				"+" +
				countryCode +
				cleaned.substring(1)
			);
		}

		// 919876543210 -> +919876543210
		if (
			new RegExp(
				`^${countryCode}\\d{10}$`
			).test(cleaned)
		) {
			return "+" + cleaned;
		}

		// 9876543210 -> +919876543210
		if (
			/^\d{10}$/.test(cleaned)
		) {
			return (
				"+" +
				countryCode +
				cleaned
			);
		}

		return cleaned;
	}

	/**
	 * Normalize and validate mobile number.
	 */
	function validateMobile(
		value,
		isSubmitting = false
	) {
		const mobile =
			normalizeMobileNumber(
				String(value || "").trim(),
				isIndiaSelected()
			);

		if (!mobile) {
			return true;
		}

		setValue(
			CONFIG.fields.mobile,
			mobile
		);

		if (
			!CONFIG.patterns.mobile.test(
				mobile
			)
		) {
			notify(
				CONFIG.messages
				.mobileInvalid, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// Start/reuse duplicate check.
		ensureDuplicateCheck(
			"mobile",
			mobile
		);

		return true;
	}

	// =========================================================================
	// 12. PIN CODE VALIDATION
	// =========================================================================

	/**
	 * Validate PIN format and perform an advisory state check.
	 */
	function validatePincode(
		value,
		isSubmitting = false
	) {
		if (!isIndiaSelected()) {
			return true;
		}

		const pincode =
			String(value || "").trim();

		if (!pincode) {
			return true;
		}

		setValue(
			CONFIG.fields.pincode,
			pincode
		);

		if (
			!CONFIG.patterns.pincode.test(
				pincode
			)
		) {
			notify(
				CONFIG.messages
				.pincodeInvalid, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// PIN/state validation is advisory only.
		checkPincodeState(pincode);

		return true;
	}

	/**
	 * Perform a coarse PIN-code/state plausibility check.
	 *
	 * This must remain advisory because PIN prefixes can cover more than one
	 * state/territory.
	 */
	function checkPincodeState(
		pincode
	) {
		const selectedState =
			trimValue(
				CONFIG.fields.state
			);

		if (!selectedState) {
			return;
		}

		const possibleStates =
			CONFIG
			.pincodeFirstDigitStates[
				pincode.charAt(0)
			];

		if (
			!possibleStates ||
			possibleStates.length === 0
		) {
			return;
		}

		const normalizedSelectedState =
			normalizeStateName(
				selectedState
			);

		const plausible =
			possibleStates.some(
				(stateName) =>
				normalizeStateName(
					stateName
				) ===
				normalizedSelectedState
			);

		if (!plausible) {
			notify(
				CONFIG.messages
				.pincodeStateMismatch(
					pincode,
					selectedState
				)
			);
		}
	}

	// =========================================================================
	// 13. SUPPLIER NAME VALIDATION
	// =========================================================================

	/**
	 * Validate supplier name and start duplicate checking.
	 */
	function validateSupplierName(
		value,
		isSubmitting = false
	) {
		const supplierName =
			String(value || "").trim();

		if (!supplierName) {
			return true;
		}

		setValue(
			CONFIG.fields.supplierName,
			supplierName
		);

		if (
			supplierName.toLowerCase() ===
			"supplier"
		) {
			notify(
				CONFIG.messages
				.supplierNameTooGeneric, {
					isBlocking: isSubmitting
				}
			);

			return false;
		}

		// Start/reuse duplicate check.
		ensureDuplicateCheck(
			"supplierName",
			supplierName
		);

		return true;
	}

	// =========================================================================
	// 14. DUPLICATE CHECK CONFIGURATION
	// =========================================================================
	//
	// Each duplicate field has:
	//
	//     - Web Form field name used by the API
	//     - Message shown when a duplicate exists
	// =========================================================================

	const duplicateTargets = {
		gstin: {
			fieldname: CONFIG.fields.gstin,

			message: CONFIG.messages
				.duplicateGstin
		},

		pan: {
			fieldname: CONFIG.fields.pan,

			message: CONFIG.messages
				.duplicatePan
		},

		email: {
			fieldname: CONFIG.fields.email,

			message: CONFIG.messages
				.duplicateEmail
		},

		mobile: {
			fieldname: CONFIG.fields.mobile,

			message: CONFIG.messages
				.duplicateMobile
		},

		supplierName: {
			fieldname: CONFIG.fields
				.supplierName,

			message: CONFIG.messages
				.duplicateSupplierName
		}
	};

	// =========================================================================
	// 15. DUPLICATE CHECK CACHE
	// =========================================================================
	//
	// Each field gets its own Map:
	//
	//     field -> Map(normalizedValue -> result)
	//
	// Result structure:
	//
	//     {
	//         pending: Boolean,
	//         checked: Boolean,
	//         duplicate: Boolean,
	//         requestId: Number
	//     }
	//
	// This design eliminates the old global pending counter and prevents the
	// same value from repeatedly triggering asynchronous requests.
	// =========================================================================

	const duplicateCache = {
		gstin: new Map(),
		pan: new Map(),
		email: new Map(),
		mobile: new Map(),
		supplierName: new Map()
	};

	let nextDuplicateRequestId = 0;

	/**
	 * Get cached duplicate result for a field/value.
	 */
	function getDuplicateEntry(
		internalFieldname,
		value
	) {
		const cache =
			duplicateCache[
				internalFieldname
			];

		if (!cache) {
			return null;
		}

		return (
			cache.get(
				String(value || "").trim()
			) || null
		);
	}

	/**
	 * Start a duplicate check if the current value has not already been
	 * checked or is not currently being checked.
	 */
	function ensureDuplicateCheck(
		internalFieldname,
		value
	) {
		const target =
			duplicateTargets[
				internalFieldname
			];

		if (!target) {
			return;
		}

		const normalizedValue =
			String(value || "").trim();

		if (!normalizedValue) {
			return;
		}

		const cache =
			duplicateCache[
				internalFieldname
			];

		let entry =
			cache.get(
				normalizedValue
			);

		/*
		 * IMPORTANT:
		 *
		 * If the exact same value is already being checked or has already
		 * been checked successfully, do not make another request.
		 */
		if (
			entry &&
			(entry.pending ||
				entry.checked)
		) {
			return;
		}

		const requestId =
			++nextDuplicateRequestId;

		entry = {
			pending: true,
			checked: false,
			duplicate: false,
			requestId
		};

		cache.set(
			normalizedValue,
			entry
		);

		frappe.call({
			method: CONFIG.duplicateCheckMethod,

			args: {
				fieldname: target.fieldname,

				value: normalizedValue,

				// Exclude the current document when editing.
				exclude_name: frappe.web_form.doc &&
					frappe.web_form.doc.name
			},

			callback: (response) => {
				const current =
					cache.get(
						normalizedValue
					);

				/*
				 * Ignore stale responses.
				 *
				 * If another request with a newer requestId has replaced this
				 * entry, this response is no longer authoritative.
				 */
				if (
					!current ||
					current.requestId !==
					requestId
				) {
					return;
				}

				current.pending = false;
				current.checked = true;

				current.duplicate = !!(
					response &&
					response.message &&
					response.message
					.is_duplicate
				);

				if (
					current.duplicate
				) {
					notify(
						target.message
					);
				}
			},

			error: () => {
				const current =
					cache.get(
						normalizedValue
					);

				if (
					!current ||
					current.requestId !==
					requestId
				) {
					return;
				}

				/*
				 * Do not mark a failed server request as "safe".
				 *
				 * checked remains false so the next Submit attempt can retry.
				 */
				current.pending = false;
				current.checked = false;
				current.duplicate = false;
			}
		});
	}

	/**
	 * Return the current duplicate-check status.
	 *
	 * Possible statuses:
	 *
	 *     not_required
	 *     not_checked
	 *     pending
	 *     checked
	 */
	function getDuplicateStatus(
		internalFieldname,
		value
	) {
		const normalizedValue =
			String(value || "").trim();

		if (!normalizedValue) {
			return {
				status: "not_required",
				duplicate: false
			};
		}

		const entry =
			getDuplicateEntry(
				internalFieldname,
				normalizedValue
			);

		if (!entry) {
			return {
				status: "not_checked",
				duplicate: false
			};
		}

		if (entry.pending) {
			return {
				status: "pending",
				duplicate: false
			};
		}

		if (!entry.checked) {
			return {
				status: "not_checked",
				duplicate: false
			};
		}

		return {
			status: "checked",
			duplicate: entry.duplicate === true
		};
	}

	// =========================================================================
	// 16. STATE / COUNTRY REVALIDATION
	// =========================================================================

	/**
	 * Revalidate fields affected by State changes.
	 */
	function revalidateAgainstState() {
		if (!isIndiaSelected()) {
			return;
		}

		const gstin =
			getValidatedGstin();

		if (gstin) {
			validateGstinState(
				gstin,
				false
			);
		}

		const pincode =
			trimValue(
				CONFIG.fields.pincode
			);

		if (
			CONFIG.patterns.pincode.test(
				pincode
			)
		) {
			checkPincodeState(
				pincode
			);
		}
	}

	/**
	 * Revalidate India-specific fields after Country changes.
	 */
	function revalidateAgainstCountry() {
		validateGstin(
			getValue(
				CONFIG.fields.gstin
			),
			false
		);

		validatePan(
			getValue(
				CONFIG.fields.pan
			),
			false
		);

		validatePincode(
			getValue(
				CONFIG.fields.pincode
			),
			false
		);

		validateMobile(
			getValue(
				CONFIG.fields.mobile
			),
			false
		);
	}

	// =========================================================================
	// 17. BLUR EVENT BINDING
	// =========================================================================

	/**
	 * Bind field-level validation to blur.
	 *
	 * Direct input events are preferred. Frappe's field event API is used as
	 * a fallback for fields that do not expose a direct input element.
	 */
	function bindBlurValidation(
		fieldname,
		handler
	) {
		const field =
			frappe.web_form.fields_dict &&
			frappe.web_form.fields_dict[
				fieldname
			];

		if (
			field &&
			field.$input &&
			typeof field.$input.on ===
			"function"
		) {
			field.$input.on(
				"blur",
				() => {
					handler(
						getValue(fieldname)
					);
				}
			);

			return;
		}

		frappe.web_form.on(
			fieldname,
			(_field, value) => {
				handler(value);
			}
		);
	}

	// =========================================================================
	// 18. FIELD EVENTS
	// =========================================================================

	// GSTIN
	bindBlurValidation(
		CONFIG.fields.gstin,
		(value) =>
		validateGstin(
			value,
			false
		)
	);

	// PAN
	bindBlurValidation(
		CONFIG.fields.pan,
		(value) =>
		validatePan(
			value,
			false
		)
	);

	// Email
	bindBlurValidation(
		CONFIG.fields.email,
		(value) =>
		validateEmail(
			value,
			false
		)
	);

	// Mobile
	bindBlurValidation(
		CONFIG.fields.mobile,
		(value) =>
		validateMobile(
			value,
			false
		)
	);

	// PIN Code
	bindBlurValidation(
		CONFIG.fields.pincode,
		(value) =>
		validatePincode(
			value,
			false
		)
	);

	// Supplier Name
	bindBlurValidation(
		CONFIG.fields.supplierName,
		(value) =>
		validateSupplierName(
			value,
			false
		)
	);

	// State
	bindBlurValidation(
		CONFIG.fields.state,
		() =>
		revalidateAgainstState()
	);

	// Country
	bindBlurValidation(
		CONFIG.fields.country,
		() =>
		revalidateAgainstCountry()
	);

	// =========================================================================
	// 19. FINAL FORM SUBMISSION VALIDATION
	// =========================================================================
	//
	// Frappe Web Form validation is synchronous:
	//
	//     return true  -> allow submission
	//     return false -> block submission
	//
	// Duplicate checks are asynchronous, so the workflow is:
	//
	// FIRST SUBMIT
	//     |
	//     +-- Start missing duplicate checks
	//     +-- Block submission
	//
	// NEXT SUBMIT
	//     |
	//     +-- Reuse completed cached results
	//     +-- Block only if duplicate/pending
	//     +-- Submit when all checks are complete
	//
	// This is the important fix that prevents repeated duplicate requests.
	// =========================================================================

	frappe.web_form.validate = () => {
		// ---------------------------------------------------------------------
		// Read and normalize current values.
		// ---------------------------------------------------------------------

		const gstin =
			trimValue(
				CONFIG.fields.gstin
			).toUpperCase();

		const email =
			trimValue(
				CONFIG.fields.email
			).toLowerCase();

		const mobile =
			normalizeMobileNumber(
				trimValue(
					CONFIG.fields.mobile
				),
				isIndiaSelected()
			);

		const pincode =
			trimValue(
				CONFIG.fields.pincode
			);

		const supplierName =
			trimValue(
				CONFIG.fields.supplierName
			);

		// ---------------------------------------------------------------------
		// Persist normalized values.
		// ---------------------------------------------------------------------

		if (gstin) {
			setValue(
				CONFIG.fields.gstin,
				gstin
			);
		}

		if (email) {
			setValue(
				CONFIG.fields.email,
				email
			);
		}

		if (mobile) {
			setValue(
				CONFIG.fields.mobile,
				mobile
			);
		}

		if (pincode) {
			setValue(
				CONFIG.fields.pincode,
				pincode
			);
		}

		if (supplierName) {
			setValue(
				CONFIG.fields.supplierName,
				supplierName
			);
		}

		// ---------------------------------------------------------------------
		// 1. Validate GSTIN.
		// ---------------------------------------------------------------------

		if (
			gstin &&
			!validateGstin(
				gstin,
				true
			)
		) {
			return false;
		}

		/*
		 * IMPORTANT:
		 *
		 * GSTIN validation can automatically change PAN.
		 * Therefore PAN must be read AFTER GSTIN validation.
		 *
		 * This prevents validation from using a stale PAN variable.
		 */
		const pan =
			trimValue(
				CONFIG.fields.pan
			).toUpperCase();

		if (pan) {
			setValue(
				CONFIG.fields.pan,
				pan
			);
		}

		// ---------------------------------------------------------------------
		// 2. Validate PAN.
		// ---------------------------------------------------------------------

		if (
			pan &&
			!validatePan(
				pan,
				true
			)
		) {
			return false;
		}

		// ---------------------------------------------------------------------
		// 3. Validate Email.
		// ---------------------------------------------------------------------

		if (
			email &&
			!validateEmail(
				email,
				true
			)
		) {
			return false;
		}

		// ---------------------------------------------------------------------
		// 4. Validate Mobile.
		// ---------------------------------------------------------------------

		if (
			mobile &&
			!validateMobile(
				mobile,
				true
			)
		) {
			return false;
		}

		// ---------------------------------------------------------------------
		// 5. Validate PIN Code.
		// ---------------------------------------------------------------------

		if (
			pincode &&
			!validatePincode(
				pincode,
				true
			)
		) {
			return false;
		}

		// ---------------------------------------------------------------------
		// 6. Validate Supplier Name.
		// ---------------------------------------------------------------------

		if (
			supplierName &&
			!validateSupplierName(
				supplierName,
				true
			)
		) {
			return false;
		}

		// ---------------------------------------------------------------------
		// 7. Verify duplicate checks.
		// ---------------------------------------------------------------------

		const duplicateFields = [{
				key: "gstin",
				value: gstin,
				message: CONFIG.messages
					.duplicateGstin
			},

			{
				key: "pan",
				value: pan,
				message: CONFIG.messages
					.duplicatePan
			},

			{
				key: "email",
				value: email,
				message: CONFIG.messages
					.duplicateEmail
			},

			{
				key: "mobile",
				value: mobile,
				message: CONFIG.messages
					.duplicateMobile
			},

			{
				key: "supplierName",
				value: supplierName,
				message: CONFIG.messages
					.duplicateSupplierName
			}
		];

		for (
			const field of
				duplicateFields
		) {
			// Empty values do not require duplicate checking.
			if (!field.value) {
				continue;
			}

			const status =
				getDuplicateStatus(
					field.key,
					field.value
				);

			// ---------------------------------------------------------------
			// Duplicate confirmed.
			// ---------------------------------------------------------------

			if (
				status.status ===
				"checked" &&
				status.duplicate
			) {
				notify(
					field.message, {
						isBlocking: true
					}
				);

				return false;
			}

			// ---------------------------------------------------------------
			// Duplicate request still running.
			// ---------------------------------------------------------------

			if (
				status.status ===
				"pending"
			) {
				notify(
					CONFIG.messages
					.duplicateCheckPending, {
						isBlocking: true
					}
				);

				return false;
			}

			// ---------------------------------------------------------------
			// No completed result exists.
			//
			// Start exactly one request and stop submission. The next Submit
			// will reuse the result once the request has completed.
			// ---------------------------------------------------------------

			if (
				status.status ===
				"not_checked"
			) {
				ensureDuplicateCheck(
					field.key,
					field.value
				);

				notify(
					CONFIG.messages
					.duplicateCheckPending, {
						isBlocking: true
					}
				);

				return false;
			}
		}

		// ---------------------------------------------------------------------
		// All validations passed.
		// ---------------------------------------------------------------------

		return true;
	};

	// =========================================================================
	// 20. SUCCESS PAGE CLEANUP
	// =========================================================================

	/**
	 * Hide the default "Submit Another Response" link.
	 */
	$(".success-footer").hide();
	$(
		".success-footer a:contains('Submit Another Response')"
	).hide();
})();

frappe.web_form.after_load = () => {
    // Determine the requested ledger type from the Web Form.
    // For a Customer ledger, use "Customer"; for a Supplier ledger,
    // use "Supplier".
    const partyType = frappe.web_form.get_value("party_type");

    // Require a valid party type before requesting ledger data.
    if (!["Customer", "Supplier"].includes(partyType)) {
        frappe.msgprint(
            __("Please select Customer or Supplier.")
        );
        return;
    }

    // Fetch ledger data from the server.
    // The server verifies that the requested party belongs to the
    // currently logged-in portal user.
    frappe.call({
        method: "get_portal_ledger",
        args: {
            party_type: partyType
        },
        callback: function (r) {
            const data = r.message;

            // Stop if the server returned no ledger context.
            if (!data) {
                frappe.msgprint(
                    __("Unable to load your ledger.")
                );
                return;
            }

            // The server-resolved party is authoritative.
            // Do not use a client-supplied party value here.
            console.log("Ledger Party:", data.party);
            console.log("Party Type:", data.party_type);
            console.log("Entries:", data.entries);
        }
    });
};
